const docks=['left','right','top','bottom'];
export function initDockPanel(panel,handle,toggle){let dock=localStorage.getItem('plane-panel-dock')||'right',size=Number(localStorage.getItem('plane-panel-size'))||280;const apply=()=>{document.body.dataset.sidebarDock=dock;document.documentElement.style.setProperty(dock==='top'||dock==='bottom'?'--sidebar-h':'--sidebar',size+'px');};const setDock=value=>{dock=docks.includes(value)?value:'right';size=dock==='top'||dock==='bottom'?Math.max(190,Math.min(440,size)):Math.max(220,Math.min(500,size));localStorage.setItem('plane-panel-dock',dock);apply();};apply();let drag=null;handle.addEventListener('pointerdown',e=>{if(e.target.closest('button,input'))return;drag={x:e.clientX,y:e.clientY};handle.setPointerCapture(e.pointerId);panel.classList.add('panel-dragging')});handle.addEventListener('pointerup',e=>{if(!drag)return;const moved=Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>10;drag=null;panel.classList.remove('panel-dragging');if(!moved)return;const distances={left:e.clientX,right:innerWidth-e.clientX,top:e.clientY,bottom:innerHeight-e.clientY};setDock(Object.entries(distances).sort((a,b)=>a[1]-b[1])[0][0]);});panel.querySelector('[data-panel-resize]')?.addEventListener('pointerdown',e=>{e.preventDefault();const start={x:e.clientX,y:e.clientY,size};e.currentTarget.setPointerCapture(e.pointerId);const move=event=>{if(dock==='left')size=start.size+event.clientX-start.x;if(dock==='right')size=start.size-event.clientX+start.x;if(dock==='top')size=start.size+event.clientY-start.y;if(dock==='bottom')size=start.size-event.clientY+start.y;size=dock==='top'||dock==='bottom'?Math.max(190,Math.min(innerHeight*.65,size)):Math.max(220,Math.min(innerWidth*.55,size));apply()};const up=()=>{localStorage.setItem('plane-panel-size',String(Math.round(size)));document.removeEventListener('pointermove',move);document.removeEventListener('pointerup',up)};document.addEventListener('pointermove',move);document.addEventListener('pointerup',up)});panel.addEventListener('click',e=>{const next=e.target.closest('[data-panel-dock]')?.dataset.panelDock;if(next)setDock(next);if(e.target.closest('[data-panel-collapse]'))toggle.click();});return {setDock};}
